final class BatchReceiptDto {
  const BatchReceiptDto({
    required this.accepted,
    required this.duplicate,
    required this.rejected,
    required this.acknowledged,
  });
  final List<String> accepted;
  final List<String> duplicate;
  final List<RejectedSampleDto> rejected;
  final List<String> acknowledged;
  factory BatchReceiptDto.fromJson(Map<String, dynamic> json) {
    final rawAccepted = json['accepted'];
    if (rawAccepted is! List) {
      throw const FormatException('Invalid BatchReceiptDto.accepted');
    }
    final accepted = List<String>.unmodifiable(
      rawAccepted.map((item) {
        if (item is! String) {
          throw const FormatException('Invalid BatchReceiptDto.accepted item');
        }
        return item;
      }),
    );
    final rawDuplicate = json['duplicate'];
    if (rawDuplicate is! List) {
      throw const FormatException('Invalid BatchReceiptDto.duplicate');
    }
    final duplicate = List<String>.unmodifiable(
      rawDuplicate.map((item) {
        if (item is! String) {
          throw const FormatException('Invalid BatchReceiptDto.duplicate item');
        }
        return item;
      }),
    );
    final rawRejected = json['rejected'];
    if (rawRejected is! List) {
      throw const FormatException('Invalid BatchReceiptDto.rejected');
    }
    final rejected = List<RejectedSampleDto>.unmodifiable(
      rawRejected.map((item) {
        if (item is! Map<String, dynamic>) {
          throw const FormatException('Invalid BatchReceiptDto.rejected item');
        }
        return RejectedSampleDto.fromJson(item);
      }),
    );
    final rawAcknowledged = json['acknowledged'];
    if (rawAcknowledged is! List) {
      throw const FormatException('Invalid BatchReceiptDto.acknowledged');
    }
    final acknowledged = List<String>.unmodifiable(
      rawAcknowledged.map((item) {
        if (item is! String) {
          throw const FormatException(
            'Invalid BatchReceiptDto.acknowledged item',
          );
        }
        return item;
      }),
    );
    return BatchReceiptDto(
      accepted: accepted,
      duplicate: duplicate,
      rejected: rejected,
      acknowledged: acknowledged,
    );
  }
  Map<String, dynamic> toJson() => {
    'accepted': accepted,
    'duplicate': duplicate,
    'rejected': rejected.map((item) => item.toJson()).toList(growable: false),
    'acknowledged': acknowledged,
  };
}

